"""practice_toc.py [--check]: the table of contents at the top of each code_library/<topic>/README.md

Lists every template section with its solved and total practice problems, between the TOC markers under the title.
Without arguments it rewrites the stale tables; --check only lists them and exits 1 when any is stale.
"""
import collections
import glob
import re
import sys

BEGIN, END = '<!-- toc: generated by .github/scripts/practice_toc.py -->', '<!-- /toc -->'


def slug(title):
    """GitHub's heading anchor: lowercase, punctuation other than - and _ dropped, spaces to -."""
    return re.sub(r'[^\w\- ]', '', title.lower()).replace(' ', '-')


def toc(text):
    """The table for a README's text: one line per section, a solved count of entries carrying a ✔ link."""
    seen, sections = collections.Counter(), []
    for line in text.split('\n'):
        m = re.match(r'#### \[(.+?)\]', line)
        if m:
            anchor = slug(m.group(1))
            if seen[anchor]:
                anchor += f'-{seen[anchor]}'
            seen[slug(m.group(1))] += 1
            sections.append([m.group(1), anchor, 0, 0])
        elif sections and line.startswith('- ['):
            sections[-1][3] += 1
            sections[-1][2] += '[✔](../../practice/' in line
    rows = [f'- [{title}](#{anchor}) · {solved}/{total}' for title, anchor, solved, total in sections]
    return '\n'.join([BEGIN, ''] + rows + ['', END])


def with_toc(text):
    """text with its table replaced, or inserted after the title line when it has none yet."""
    table = toc(text)
    if BEGIN in text:
        start, end = text.index(BEGIN), text.index(END) + len(END)
        return text[:start] + table + text[end:]
    title_end = text.index('\n') + 1
    return text[:title_end] + '\n' + table + '\n' + text[title_end:]


def main():
    stale = []
    for path in sorted(glob.glob('code_library/*/README.md')):
        text = open(path, encoding='utf-8').read()
        new = with_toc(text)
        if new != text:
            stale.append(path)
            if '--check' not in sys.argv:
                open(path, 'w', encoding='utf-8').write(new)
    for path in stale:
        print(path)
    return 1 if stale and '--check' in sys.argv else 0


if __name__ == '__main__':
    sys.exit(main())
